     3	export const MINUTE_IN_MS = 60_000;
     4	
     5	export function parseInstant(value: string): Date {
     6	  const parsed = new Date(value);
     7	  if (Number.isNaN(parsed.getTime())) {
     8	    throw validationFailed('Value is not a valid instant', { value });
     9	  }
    10	  return parsed;
    11	}
    12	
    13	export function durationMinutes(start: Date, end: Date): number {
    14	  return Math.round((end.getTime() - start.getTime()) / MINUTE_IN_MS);
    15	}
    16	
    17	export function isBefore(a: Date, b: Date): boolean {
    18	  return a.getTime() < b.getTime();
    19	}
